18	export default async function ColdEmailBrands() {
19	  await requireArea("platform");
20	
21	  const [brands, protectedRaw] = await Promise.all([
22	    db.brand.findMany({ orderBy: { createdAt: "asc" } }),
23	    getSetting("cold_email_protected_domains"),
24	  ]);
25	  const protectedSet = protectedDomainSet(protectedRaw, appHost());
26	
27	  return (
28	    <div className="space-y-6">
29	      <PageHeader
30	        title="Brands"
31	        sub="Sending identities. A brand may only send with a physical address, verified SPF/DKIM/DMARC, and a dedicated (non-platform) sending domain."
32	      />
33	
34	      <div className="card">
35	        <p className="section-label mb-4">Add a brand</p>
36	        <BrandForm />
37	      </div>
38	
39	      {brands.length === 0 ? (
40	        <EmptyState title="No brands yet" sub="Add a sending identity above." />
41	      ) : (
42	        <div className="space-y-4">
43	          {brands.map((b) => {
44	            const elig = evaluateSendEligibility(b, protectedSet);
45	            return (
46	              <div key={b.id} className="card">
47	                <div className="mb-4 flex flex-wrap items-center justify-between gap-3">
48	                  <div className="flex items-center gap-2">
49	                    <span className="font-medium text-white">{b.name}</span>
50	                    {elig.eligible ? (
51	                      <Badge tone="green">eligible to send</Badge>
52	                    ) : (
53	                      <Badge tone="red">not eligible</Badge>
54	                    )}
55	                    {b.sendingPaused && <Badge tone="amber">paused</Badge>}
56	                  </div>
57	                  <div className="flex items-center gap-2">
58	                    {b.sendingPaused && <ClearBrandPauseButton brandId={b.id} />}
59	                    <BrandDelete id={b.id} />
60	                  </div>
61	                </div>
62	
63	                {/* Send-eligibility checklist */}
64	                <div className="mb-4 grid gap-2 sm:grid-cols-2 lg:grid-cols-5">
65	                  {elig.checks.map((c) => (
66	                    <div
67	                      key={c.key}
68	                      className={`flex items-center gap-2 rounded-lg border px-3 py-2 text-xs ${
69	                        c.ok
70	                          ? "border-emerald-500/30 bg-emerald-500/[0.06] text-emerald-300"
71	                          : "border-red-500/30 bg-red-500/[0.06] text-red-300"
72	                      }`}
73	                    >
74	                      <span aria-hidden>{c.ok ? "●" : "○"}</span>
75	                      <span>{c.label}</span>
76	                    </div>
77	                  ))}
78	                </div>
79	                {b.sendingPaused && b.pausedReason && (
80	                  <p className="mb-4 rounded-lg border border-amber-500/30 bg-amber-500/[0.06] px-3 py-2 text-xs text-amber-300">
81	                    {b.pausedReason}
82	                  </p>
83	                )}
84	
85	                <BrandForm
86	                  brand={{
87	                    id: b.id,
88	                    name: b.name,
89	                    fromName: b.fromName,
90	                    fromEmail: b.fromEmail,
91	                    sendingDomain: b.sendingDomain,
92	                    physicalPostalAddress: b.physicalPostalAddress,
93	                    replyTo: b.replyTo,
94	                    spfVerified: b.spfVerified,
95	                    dkimVerified: b.dkimVerified,
96	                    dmarcVerified: b.dmarcVerified,
97	                  }}
98	                />
99	              </div>
100	            );
101	          })}
102	        </div>
103	      )}
