1	import { db } from "@/lib/db";
2	import { requireArea } from "@/lib/rbac";
3	import { PageHeader, Badge, StatusDot, EmptyState } from "@/components/ui/primitives";
4	import {
5	  SendingDomainForm,
6	  DomainVerificationForm,
7	  DomainStatusButtons,
8	  InboxForm,
9	  InboxControls,
10	} from "@/components/admin/coldemail/Phase3Controls";
11	import { warmupStatus } from "@/lib/coldemail/warmup";
12	import { warmupDayIndex } from "@/lib/coldemail/compliance";
13	
14	export const dynamic = "force-dynamic";
15	
16	// The 2026 mandatory-NOW readiness checklist per sending domain (research §5).
17	function domainReadiness(d: {
