150	/**
151	 * Run the four authentication checks for `domain`.
152	 *
153	 * `mailHost` is the MX we expect, `spfInclude` the mechanism that authorises our
154	 * sending host, and `dkim` MUST be the LIVE key read from Mailcow
155	 * (`GET /get/dkim/<domain>` → `dkim_txt`), never the cached
156	 * `EmailSubscription.dkimRecord`: a stale cache would confirm a key that no
157	 * longer signs anything.
158	 */
159	export async function checkDeliverability(opts: {
160	  domain: string;
161	  mailHost: string;
162	  spfInclude: string;
163	  spfExpected: string;
164	  dmarcExpected: string;
165	  dkim: { selector: string; txt: string } | null;
166	}): Promise<DeliverabilityReport> {
167	  const domain = opts.domain.trim().toLowerCase().replace(/\.$/, "");
168	  const checkedAt = new Date().toISOString();
169	  const dkimSelector = opts.dkim?.selector || "dkim";
170	  const dkimHost = `${dkimSelector}._domainkey.${domain}`;
171	
172	  const auth = await authoritativeResolver(domain);
173	  if ("error" in auth) {
174	    const unknown = (
175	      key: DeliverabilityCheck["key"],
176	      label: string,
177	      host: string,
178	      type: DeliverabilityCheck["type"],
179	      expected: string,
180	    ): DeliverabilityCheck => ({
181	      key,
182	      label,
183	      status: "unknown",
184	      observed: "",
185	      expected,
186	      detail: "Couldn't reach this domain's nameservers to read the record.",
187	      host,
188	      type,
189	    });
190	    return {
191	      domain,
192	      nameservers: [],
193	      error: auth.error,
194	      checkedAt,
195	      checks: [
196	        unknown("mx", "MX — mail routing", domain, "MX", opts.mailHost),
197	        unknown("spf", "SPF — authorised senders", domain, "TXT", opts.spfExpected),
198	        unknown("dkim", "DKIM — message signing", dkimHost, "TXT", opts.dkim?.txt ?? "(no key on the mail server yet)"),
199	        unknown("dmarc", "DMARC — policy", `_dmarc.${domain}`, "TXT", opts.dmarcExpected),
200	      ],
201	    };
202	  }
203	
204	  const { resolver, nameservers } = auth;
205	
206	  const [mxRecords, apexTxt, dkimTxt, dmarcTxt] = await Promise.all([
207	    resolver.resolveMx(domain).catch(() => null),
208	    txtAt(resolver, domain),
209	    txtAt(resolver, dkimHost),
210	    txtAt(resolver, `_dmarc.${domain}`),
211	  ]);
212	
213	  const checks: DeliverabilityCheck[] = [];
214	
215	  // ---- MX ----------------------------------------------------------------
216	  {
217	    const rows = (mxRecords ?? []).map((r) => ({
218	      exchange: r.exchange.replace(/\.$/, "").toLowerCase(),
219	      priority: r.priority,
220	    }));
221	    const observed = rows.length
222	      ? rows
223	          .slice()
224	          .sort((a, b) => a.priority - b.priority)
225	          .map((r) => `${r.exchange} (${r.priority})`)
226	          .join(", ")
227	      : "";
228	    const ours = rows.some((r) => r.exchange === opts.mailHost);
229	    checks.push({
230	      key: "mx",
231	      label: "MX — mail routing",
232	      status: ours ? (rows.length > 1 ? "warn" : "pass") : "fail",
233	      observed,
234	      // Hostname only, deliberately: the setup panel suggests priority 10, but any
235	      // priority works when this is the only MX. Printing "(priority 10)" next to
236	      // a healthy `mail.nxeon.cloud (1)` made a passing row look like a mismatch.
237	      expected: opts.mailHost,
238	      host: domain,
239	      type: "MX",
240	      detail: !rows.length
241	        ? `No MX record published — inbound mail for this domain has nowhere to go. Add an MX for ${opts.mailHost} at priority 10.`
242	        : ours
243	          ? rows.length > 1
244	            ? "Our mail host is listed, but so are others — mail may be delivered to a different server."
245	            : "Inbound mail is routed to the Nxeon mail server."
246	          : `Mail is routed elsewhere. Point the MX at ${opts.mailHost} (priority 10) or inbound mail will never reach these mailboxes.`,
247	    });
248	  }
249	
250	  // ---- SPF ---------------------------------------------------------------
251	  {
252	    const spfRecords = (apexTxt ?? []).filter((t) => /^v=spf1\b/i.test(t));
253	    const observed = spfRecords.join(" | ");
254	    let status: CheckStatus = "fail";
255	    let detail: string;
256	    if (spfRecords.length === 0) {
257	      detail = "No SPF record published — receivers have nothing authorising us to send for you.";
258	    } else if (spfRecords.length > 1) {
259	      status = "fail";
260	      detail = "More than one SPF record. RFC 7208 makes that a permanent error — merge them into one.";
261	    } else {
262	      const spf = spfRecords[0];
263	      const authorised =
264	        spf.toLowerCase().includes(`include:${opts.spfInclude}`) ||
265	        // `mx` authorises whatever the MX points at, which is our mail host when
266	        // the MX check above passes — a valid, commonly-used alternative.
267	        /(?:^|\s)mx(?:\s|$)/i.test(spf);
268	      if (authorised) {
269	        status = /[~-]all\s*$/.test(spf) ? "pass" : "warn";
270	        detail =
271	          status === "pass"
272	            ? "The Nxeon mail server is authorised to send for this domain."
273	            : "Authorised, but the record has no `~all`/`-all` terminator, so receivers apply no policy to unauthorised senders.";
274	      } else {
275	        detail = `SPF exists but doesn't authorise us. Add \`include:${opts.spfInclude}\` (or \`mx\`) or your mail will be treated as spoofed.`;
276	      }
277	    }
278	    checks.push({
279	      key: "spf",
280	      label: "SPF — authorised senders",
281	      status,
282	      observed,
283	      expected: opts.spfExpected,
284	      host: domain,
285	      type: "TXT",
286	      detail,
287	    });
288	  }
289	
290	  // ---- DKIM --------------------------------------------------------------
291	  {
292	    const published = (dkimTxt ?? []).find((t) => /(?:^|[;\s])p=/.test(t)) ?? "";
293	    const expected = opts.dkim?.txt ?? "";
294	    let status: CheckStatus = "fail";
295	    let detail: string;
296	    if (!expected) {
297	      status = "unknown";
298	      detail =
299	        "The mail server hasn't generated a DKIM key for this domain yet — there is nothing to publish. Reload in a moment.";
300	    } else if (!published) {
301	      detail = `No DKIM record at ${dkimHost}. Without it every message you send is unsigned, which is the single biggest reason mail lands in spam.`;
302	    } else if (dkimKey(published) && dkimKey(published) === dkimKey(expected)) {
303	      status = "pass";
304	      detail = `Published key matches the one the mail server signs with (selector \`${dkimSelector}\`).`;
305	    } else {
306	      detail =
307	        "A DKIM record exists but the public key does not match the mail server's current key — signatures will fail. Replace it with the value shown here.";
308	    }
309	    checks.push({
310	      key: "dkim",
311	      label: "DKIM — message signing",
312	      status,
313	      observed: truncate(published),
314	      expected: truncate(expected || "(no key on the mail server yet)"),
315	      host: dkimHost,
316	      type: "TXT",
317	      detail,
318	    });
319	  }
320	
321	  // ---- DMARC -------------------------------------------------------------
322	  {
323	    const records = (dmarcTxt ?? []).filter((t) => /^v=DMARC1\b/i.test(t));
324	    const observed = records.join(" | ");
325	    let status: CheckStatus = "fail";
326	    let detail: string;
327	    if (records.length === 0) {
328	      detail =
329	        "No DMARC record. Some large providers now require one before they will trust bulk mail from a domain.";
330	    } else if (records.length > 1) {
331	      detail = "More than one DMARC record at _dmarc — receivers ignore all of them. Keep exactly one.";
332	    } else {
333	      const policy = records[0].match(/(?:^|;)\s*p\s*=\s*(none|quarantine|reject)/i)?.[1]?.toLowerCase();
334	      status = policy ? "pass" : "warn";
335	      detail = policy
336	        ? `Policy \`p=${policy}\` is published${policy === "none" ? " (monitor-only — tighten it once SPF and DKIM both pass)" : ""}.`
337	        : "A DMARC record exists but declares no `p=` policy, so receivers have nothing to enforce.";
338	    }
339	    checks.push({
340	      key: "dmarc",
341	      label: "DMARC — policy",
342	      status,
343	      observed,
344	      expected: opts.dmarcExpected,
345	      host: `_dmarc.${domain}`,
346	      type: "TXT",
347	      detail,
348	    });
349	  }
350	
351	  return { domain, nameservers, checks, checkedAt };
352	}
