// Cold Email Engine — LIVE DNS authentication recognition (pure core).
//
// PURE + unit-testable. This module holds NO I/O: it turns already-fetched TXT /
// CNAME answers into SPF / DKIM / DMARC verdicts. The live lookups live in the
// `verifyDomainDns` server action (lib/actions-coldemail.ts), which fetches the
// records through the zone's AUTHORITATIVE nameservers (never the local resolver
// — see lib/mail/deliverability.ts "THE RESOLVER TRAP") and hands the raw answers
// here. Keeping recognition pure means the SPF/DKIM/DMARC parsing is tested the
// same way it runs.

/** One record's verdict: did we recognise it, the raw value found, and why-not. */
export type DnsRecordCheck = {
  verified: boolean;
  /** The raw record we recognised at that host (null when nothing usable found). */
  record: string | null;
  /** Human-readable reason when not verified, or a lookup error. null when green. */
  error: string | null;
};

/** The full per-domain verdict returned by the verify action. */
export type DnsVerifyResult = {
  domain: string;
  dkimSelector: string;
  spf: DnsRecordCheck;
  dkim: DnsRecordCheck;
  dmarc: DnsRecordCheck;
  /** Present only for sending-domain checks that include a tracking CNAME. */
  tracking: (DnsRecordCheck & { host: string }) | null;
  /** ISO timestamp. */
  checkedAt: string;
  /** Set when authority for the zone could not be established at all. */
  lookupError: string | null;
};

/** Default DKIM selector when the operator does not specify one. */
export const DEFAULT_DKIM_SELECTOR = "default";

/** A TXT record's chunks are concatenated with NO separator (RFC 7208 §3.3). */
export function joinTxt(record: string[]): string {
  return record.join("").trim();
}

/** Trim + lower-case a selector; fall back to the default. Strips a stray dot. */
export function normalizeSelector(selector: string | null | undefined): string {
  const s = (selector ?? "").trim().toLowerCase().replace(/\.+$/, "");
  return s || DEFAULT_DKIM_SELECTOR;
}

// ---------------------------------------------------------------------------
// Record recognition (pure)
// ---------------------------------------------------------------------------

/** True for a TXT value that is an SPF record (starts `v=spf1`). */
export function isSpfRecord(txt: string): boolean {
  return /^v=spf1\b/i.test(txt.trim());
}

/** True for a TXT value that is a DMARC record (starts `v=DMARC1`). */
export function isDmarcRecord(txt: string): boolean {
  return /^v=DMARC1\b/i.test(txt.trim());
}

/**
 * True for a TXT value that looks like a DKIM public-key record: it carries the
 * `v=DKIM1` tag, a `k=` key-type tag, or a `p=` public-key tag (RFC 6376 §3.6.1).
 */
export function isDkimRecord(txt: string): boolean {
  const t = txt.trim();
  return /(?:^|[;\s])v=DKIM1\b/i.test(t) || /(?:^|[;\s])k=/i.test(t) || /(?:^|[;\s])p=/i.test(t);
}

/** The `p=` public-key value from a DKIM record, or "" when absent/empty. */
export function dkimPublicKey(txt: string): string {
  const m = txt.match(/(?:^|[;\s])p=([A-Za-z0-9+/=]*)/);
  return m ? m[1] : "";
}

/** The first SPF record among a set of TXT values (null if none). */
export function findSpfRecord(txts: string[]): string | null {
  return txts.find(isSpfRecord) ?? null;
}

/** The first DMARC record among a set of TXT values (null if none). */
export function findDmarcRecord(txts: string[]): string | null {
  return txts.find(isDmarcRecord) ?? null;
}

/** The first DKIM record among a set of TXT values (null if none). */
export function findDkimRecord(txts: string[]): string | null {
  return txts.find(isDkimRecord) ?? null;
}

// ---------------------------------------------------------------------------
// Verdict builders (pure) — turn fetched answers into a DnsRecordCheck
// ---------------------------------------------------------------------------

/**
 * SPF verdict. Verified when exactly one `v=spf1` record is published. More than
 * one SPF record is a permanent error (RFC 7208 §3.2) so it fails with the reason.
 * `txts === null` means the lookup returned nothing / NXDOMAIN.
 */
export function buildSpfCheck(txts: string[] | null): DnsRecordCheck {
  if (txts === null) return { verified: false, record: null, error: "No TXT records found at the domain apex." };
  const spf = txts.filter(isSpfRecord);
  if (spf.length === 0) return { verified: false, record: null, error: "No SPF record (v=spf1) published at the apex." };
  if (spf.length > 1)
    return { verified: false, record: spf.join(" | "), error: "Multiple SPF records — RFC 7208 makes that a permanent error. Merge into one." };
  return { verified: true, record: spf[0], error: null };
}

/**
 * DMARC verdict. Verified when exactly one `v=DMARC1` record is published at
 * `_dmarc.<domain>`. Multiple records make receivers ignore all of them.
 */
export function buildDmarcCheck(txts: string[] | null): DnsRecordCheck {
  if (txts === null) return { verified: false, record: null, error: "No TXT record at _dmarc — no DMARC policy published." };
  const recs = txts.filter(isDmarcRecord);
  if (recs.length === 0) return { verified: false, record: null, error: "No DMARC record (v=DMARC1) at _dmarc." };
  if (recs.length > 1)
    return { verified: false, record: recs.join(" | "), error: "Multiple DMARC records at _dmarc — receivers ignore all of them. Keep one." };
  return { verified: true, record: recs[0], error: null };
}

/**
 * DKIM verdict. Verified when a DKIM record is published at
 * `<selector>._domainkey.<domain>` AND it carries a non-empty `p=` public key (an
 * empty `p=` is a revoked key that signs nothing).
 */
export function buildDkimCheck(txts: string[] | null, selector: string): DnsRecordCheck {
  const host = `${normalizeSelector(selector)}._domainkey`;
  if (txts === null) return { verified: false, record: null, error: `No TXT record at ${host} — no DKIM key for this selector.` };
  const rec = findDkimRecord(txts);
  if (!rec) return { verified: false, record: null, error: `No DKIM record (v=DKIM1) at ${host}.` };
  if (!dkimPublicKey(rec))
    return { verified: false, record: rec, error: "DKIM record found but its public key (p=) is empty — the key is revoked." };
  return { verified: true, record: rec, error: null };
}

/**
 * Tracking-domain verdict. A custom tracking domain must be a CNAME (shared /
 * uncustomised tracking hosts tank placement). Verified when at least one CNAME
 * target resolves. `targets === null` means the lookup returned no CNAME.
 */
export function buildCnameCheck(targets: string[] | null): DnsRecordCheck {
  if (targets === null || targets.length === 0)
    return { verified: false, record: null, error: "No CNAME published for the tracking domain." };
  return { verified: true, record: targets.join(", "), error: null };
}

