export async function txtAt(resolver: Resolver, host: string): Promise<string[] | null> {
  try {
    return (await resolver.resolveTxt(host)).map(joinTxt).filter(Boolean);
  } catch {
    // NXDOMAIN / ENODATA from the authority means "not published".
    return null;
  }
}

/**
 * CNAME target(s) at `host`, resolved through the authoritative nameservers, or
 * null when nothing is published. Used for the cold-email tracking-domain check.
 */
export async function cnameAt(resolver: Resolver, host: string): Promise<string[] | null> {
  try {
    const targets = (await resolver.resolveCname(host)).map((c) => c.replace(/\.$/, "").toLowerCase()).filter(Boolean);
    return targets.length ? targets : null;
  } catch {
    return null;
  }
}

