// ---------------------------------------------------------------------------
// LIVE DNS verification (SPF / DKIM / DMARC + tracking CNAME)
//
// Real DNS lookups, NOT self-attested checkboxes. The records are read through
// the zone's AUTHORITATIVE nameservers (lib/mail/deliverability.ts) rather than
// the local resolver — this host's /etc/hosts once produced a confidently wrong
// diagnosis, so cold-email verification must never trust the system resolver.
// The pure recognition lives in lib/coldemail/dns.ts and is unit-tested.
// ---------------------------------------------------------------------------

/**
 * Run live SPF / DKIM / DMARC (and optional tracking-CNAME) lookups for `domain`.
 * Read-only: returns each record verified/not with the raw value found (or the
 * reason it failed). Does NOT write any flags — callers that persist are
 * `verifyBrandDns` / `verifySendingDomainDns`.
 */
export async function verifyDomainDns(
  domain: string,
  dkimSelector?: string,
  trackingDomain?: string,
): Promise<DnsVerifyResult> {
  await requireArea("platform");
  const host = normalizeDomain(domain);
  const selector = normalizeSelector(dkimSelector);
  const checkedAt = new Date().toISOString();
  const track = normalizeDomain(trackingDomain);

  if (!host) {
    const err = "No domain to check.";
    const fail = { verified: false, record: null, error: err };
    return { domain: host, dkimSelector: selector, spf: fail, dkim: fail, dmarc: fail, tracking: null, checkedAt, lookupError: err };
  }

  const auth = await authoritativeResolver(host);
  if ("error" in auth) {
    const fail = { verified: false, record: null, error: auth.error };
    return {
      domain: host,
      dkimSelector: selector,
      spf: fail,
      dkim: fail,
      dmarc: fail,
      tracking: track ? { host: track, verified: false, record: null, error: auth.error } : null,
      checkedAt,
      lookupError: auth.error,
    };
  }

  const { resolver } = auth;
  const [apexTxt, dkimTxt, dmarcTxt, cname] = await Promise.all([
    txtAt(resolver, host),
    txtAt(resolver, `${selector}._domainkey.${host}`),
    txtAt(resolver, `_dmarc.${host}`),
    track ? cnameAt(resolver, track) : Promise.resolve(null),
  ]);

  return {
    domain: host,
    dkimSelector: selector,
    spf: buildSpfCheck(apexTxt),
    dkim: buildDkimCheck(dkimTxt, selector),
    dmarc: buildDmarcCheck(dmarcTxt, selector),
    tracking: track ? { host: track, ...buildCnameCheck(cname) } : null,
    checkedAt,
    lookupError: null,
  };
}

/**
 * Live-verify a brand's sending domain and PERSIST the real result onto the
 * brand's spf/dkim/dmarc verified flags (never a manual checkbox). The domain
 * checked is the brand's dedicated `sendingDomain`, falling back to the From
 * address domain. Returns the full result for display.
 */
export async function verifyBrandDns(
  brandId: string,
  dkimSelector?: string,
): Promise<DnsVerifyResult | { error: string }> {
  await requireArea("platform");
  const brand = await db.brand.findUnique({
    where: { id: brandId },
    select: { sendingDomain: true, fromEmail: true },
  });
  if (!brand) return { error: "Brand not found." };
  const domain = normalizeDomain(brand.sendingDomain) || emailDomain(brand.fromEmail);
  if (!domain) return { error: "Set a sending domain (or From address) on the brand before verifying DNS." };

  const result = await verifyDomainDns(domain, dkimSelector);
  await db.brand.update({
    where: { id: brandId },
    data: {
      spfVerified: result.spf.verified,
      dkimVerified: result.dkim.verified,
      dmarcVerified: result.dmarc.verified,
    },
  });
  await logEvent("info", "coldemail.brand.dns_verify", {
    brandId,
    domain,
    spf: result.spf.verified,
    dkim: result.dkim.verified,
    dmarc: result.dmarc.verified,
  });
  revalidatePath("/admin/coldemail/brands");
  revalidatePath("/admin/coldemail");
  return result;
}

/**
 * Live-verify a sending domain (its outreach FQDN `<subdomain>.<domain>`) plus its
 * custom tracking-domain CNAME, and PERSIST the real result onto the SendingDomain
 * auth + tracking flags. Auto-advances PENDING → WARMING and stamps warmupStartedAt
 * once SPF + DKIM + DMARC are all live-green, mirroring setDomainVerification.
 */
export async function verifySendingDomainDns(
  id: string,
  dkimSelector?: string,
): Promise<DnsVerifyResult | { error: string }> {
  await requireArea("platform");
  const d = await db.sendingDomain.findUnique({
    where: { id },
    select: { domain: true, subdomain: true, trackingDomain: true, status: true, warmupStartedAt: true },
  });
  if (!d) return { error: "Sending domain not found." };
  const fqdn = normalizeDomain(`${d.subdomain}.${d.domain}`);

  const result = await verifyDomainDns(fqdn, dkimSelector, d.trackingDomain || undefined);
  const authed = result.spf.verified && result.dkim.verified && result.dmarc.verified;
  const nextStatus = d.status === "PENDING" && authed ? "WARMING" : d.status;

  await db.sendingDomain.update({
    where: { id },
    data: {
      spfVerified: result.spf.verified,
      dkimVerified: result.dkim.verified,
      dmarcVerified: result.dmarc.verified,
      trackingDomainVerified: result.tracking ? result.tracking.verified : false,
      status: nextStatus,
      lastCheckedAt: new Date(),
      warmupStartedAt: authed ? d.warmupStartedAt ?? new Date() : d.warmupStartedAt,
    },
  });
  await logEvent("info", "coldemail.domain.dns_verify", {
    id,
    domain: fqdn,
    spf: result.spf.verified,
    dkim: result.dkim.verified,
    dmarc: result.dmarc.verified,
    tracking: result.tracking?.verified ?? null,
  });
  revalidatePath("/admin/coldemail/domains");
  return result;
}

