"use client";

import { useState, useTransition } from "react";
import { verifyBrandDns, verifySendingDomainDns } from "@/lib/actions-coldemail";
import type { DnsVerifyResult, DnsRecordCheck } from "@/lib/coldemail/dns";

// LIVE DNS verification controls. These replace the self-attested SPF/DKIM/DMARC
// checkboxes as the PRIMARY path: the button runs a real DNS lookup and the server
// action writes the stored verified flags from the actual result. The manual
// checkboxes (DomainVerificationForm / BrandForm) remain as a fallback only.

type Row = { key: string; label: string; check: DnsRecordCheck; host?: string };

function ResultRow({ label, check, host }: { label: string; check: DnsRecordCheck; host?: string }) {
  return (
    <div
      className={`rounded-lg border px-3 py-2 text-xs ${
        check.verified
          ? "border-emerald-500/30 bg-emerald-500/[0.06]"
          : "border-red-500/30 bg-red-500/[0.06]"
      }`}
    >
      <div className="flex items-center gap-2">
        <span aria-hidden className={check.verified ? "text-emerald-400" : "text-red-400"}>
          {check.verified ? "●" : "○"}
        </span>
        <span className={check.verified ? "font-medium text-emerald-200" : "font-medium text-red-200"}>{label}</span>
        <span className={check.verified ? "text-emerald-400" : "text-red-400"}>{check.verified ? "verified" : "not found"}</span>
      </div>
      {host && <p className="mt-1 font-mono text-[11px] text-slate-500">{host}</p>}
      {check.record && (
        <p className="mt-1 break-all font-mono text-[11px] text-slate-400">{check.record}</p>
      )}
      {check.error && !check.verified && <p className="mt-1 text-[11px] text-red-300/80">{check.error}</p>}
    </div>
  );
}

function ResultPanel({ result }: { result: DnsVerifyResult }) {
  const rows: Row[] = [
    { key: "spf", label: "SPF", check: result.spf, host: result.domain },
    { key: "dkim", label: "DKIM", check: result.dkim, host: `${result.dkimSelector}._domainkey.${result.domain}` },
    { key: "dmarc", label: "DMARC", check: result.dmarc, host: `_dmarc.${result.domain}` },
  ];
  if (result.tracking) rows.push({ key: "tracking", label: "Tracking CNAME", check: result.tracking, host: result.tracking.host });

  return (
    <div className="space-y-2">
      {result.lookupError && (
        <div className="rounded-lg border border-amber-500/30 bg-amber-500/10 px-3 py-2 text-xs text-amber-300">
          {result.lookupError}
        </div>
      )}
      <div className="grid gap-2 sm:grid-cols-2">
        {rows.map((r) => (
          <ResultRow key={r.key} label={r.label} check={r.check} host={r.host} />
        ))}
      </div>
      <p className="text-[11px] text-slate-500">
        Live lookup via the zone&apos;s authoritative nameservers · {new Date(result.checkedAt).toLocaleString()} · stored
        verified flags updated from this result.
      </p>
    </div>
  );
}

function SelectorInput({ value, onChange }: { value: string; onChange: (v: string) => void }) {
  return (
    <label className="flex items-center gap-2 text-xs text-slate-400">
      DKIM selector
      <input
        className="input w-28 py-1 text-xs"
        value={value}
        onChange={(e) => onChange(e.target.value)}
        placeholder="default"
      />
    </label>
  );
}

export function BrandDnsVerify({ brandId, domain }: { brandId: string; domain: string }) {
  const [pending, start] = useTransition();
  const [selector, setSelector] = useState("default");
  const [result, setResult] = useState<DnsVerifyResult | null>(null);
  const [error, setError] = useState<string | null>(null);

  const run = () =>
    start(async () => {
      setError(null);
      const r = await verifyBrandDns(brandId, selector);
      if ("error" in r) {
        setError(r.error);
        setResult(null);
      } else {
        setResult(r);
      }
    });

  return (
    <div className="space-y-3 rounded-xl border border-white/[0.06] bg-white/[0.02] p-4">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <p className="section-label">
          Live DNS verification {domain ? <span className="font-mono text-xs text-slate-500">· {domain}</span> : null}
        </p>
        <div className="flex items-center gap-3">
          <SelectorInput value={selector} onChange={setSelector} />
          <button className="btn-secondary px-3 py-1.5 text-xs" disabled={pending} onClick={run}>
            {pending ? "Checking DNS…" : "Verify DNS"}
          </button>
        </div>
      </div>
      {!domain && (
        <p className="text-xs text-amber-300">Set a sending domain (or From address) on the brand to verify DNS.</p>
      )}
      {error && <div className="rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-xs text-red-400">{error}</div>}
      {result && <ResultPanel result={result} />}
    </div>
  );
}

export function SendingDomainDnsVerify({
  id,
  fqdn,
  hasTracking,
}: {
  id: string;
  fqdn: string;
  hasTracking: boolean;
}) {
  const [pending, start] = useTransition();
  const [selector, setSelector] = useState("default");
  const [result, setResult] = useState<DnsVerifyResult | null>(null);
  const [error, setError] = useState<string | null>(null);

  const run = () =>
    start(async () => {
      setError(null);
      const r = await verifySendingDomainDns(id, selector);
      if ("error" in r) {
        setError(r.error);
        setResult(null);
      } else {
        setResult(r);
      }
    });

  return (
    <div className="space-y-3">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <p className="text-xs text-slate-400">
          Live check of <span className="font-mono text-slate-300">{fqdn}</span>
          {hasTracking ? " + tracking CNAME" : ""}.
        </p>
        <div className="flex items-center gap-3">
          <SelectorInput value={selector} onChange={setSelector} />
          <button className="btn-secondary px-3 py-1.5 text-xs" disabled={pending} onClick={run}>
            {pending ? "Checking DNS…" : "Verify DNS"}
          </button>
        </div>
      </div>
      {error && <div className="rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-xs text-red-400">{error}</div>}
      {result && <ResultPanel result={result} />}
    </div>
  );
}

