import { test } from "node:test";
import assert from "node:assert/strict";
import {
  joinTxt,
  normalizeSelector,
  isSpfRecord,
  isDmarcRecord,
  isDkimRecord,
  dkimPublicKey,
  findSpfRecord,
  findDmarcRecord,
  findDkimRecord,
  buildSpfCheck,
  buildDmarcCheck,
  buildDkimCheck,
  buildCnameCheck,
  DEFAULT_DKIM_SELECTOR,
} from "../lib/coldemail/dns.ts";

// ---------------------------------------------------------------------------
// joinTxt / normalizeSelector
// ---------------------------------------------------------------------------

test("joinTxt concatenates TXT chunks with no separator (RFC 7208)", () => {
  assert.equal(joinTxt(["v=DKIM1; k=rsa; ", "p=AAAA", "BBBB"]), "v=DKIM1; k=rsa; p=AAAABBBB");
  assert.equal(joinTxt(["  v=spf1 -all  "]), "v=spf1 -all");
});

test("normalizeSelector lower-cases, trims and falls back to the default", () => {
  assert.equal(normalizeSelector(" Google "), "google");
  assert.equal(normalizeSelector("dkim."), "dkim");
  assert.equal(normalizeSelector(""), DEFAULT_DKIM_SELECTOR);
  assert.equal(normalizeSelector(null), DEFAULT_DKIM_SELECTOR);
  assert.equal(normalizeSelector(undefined), "default");
});

// ---------------------------------------------------------------------------
// Record recognition
// ---------------------------------------------------------------------------

test("isSpfRecord only matches a v=spf1 record", () => {
  assert.equal(isSpfRecord("v=spf1 include:_spf.google.com ~all"), true);
  assert.equal(isSpfRecord("V=SPF1 -all"), true);
  assert.equal(isSpfRecord("v=DMARC1; p=none"), false);
  assert.equal(isSpfRecord("some google-site-verification=abc"), false);
  // Must START with v=spf1 — a TXT that merely mentions spf1 does not count.
  assert.equal(isSpfRecord("note: v=spf1 somewhere"), false);
});

test("isDmarcRecord only matches a v=DMARC1 record", () => {
  assert.equal(isDmarcRecord("v=DMARC1; p=reject; rua=mailto:d@x.com"), true);
  assert.equal(isDmarcRecord("v=spf1 -all"), false);
  assert.equal(isDmarcRecord("v=DKIM1; k=rsa; p=AAAA"), false);
});

test("isDkimRecord matches v=DKIM1, k= or p= markers", () => {
  assert.equal(isDkimRecord("v=DKIM1; k=rsa; p=MIIBIjANBg"), true);
  assert.equal(isDkimRecord("k=rsa; p=MIIBIjANBg"), true);
  assert.equal(isDkimRecord("p=MIIBIjANBg"), true);
  assert.equal(isDkimRecord("v=spf1 -all"), false);
  assert.equal(isDkimRecord("v=DMARC1; p=none"), true); // p= present — narrowed by _domainkey host in practice
});

test("dkimPublicKey extracts the p= value, empty when revoked", () => {
  assert.equal(dkimPublicKey("v=DKIM1; k=rsa; p=MIIBIjANBg=="), "MIIBIjANBg==");
  assert.equal(dkimPublicKey("v=DKIM1; k=rsa; p="), "");
  assert.equal(dkimPublicKey("v=DKIM1; k=rsa"), "");
});

test("find* pick the first matching record out of a mixed TXT set", () => {
  const txts = [
    "google-site-verification=xyz",
    "v=spf1 include:_spf.google.com ~all",
  ];
  assert.equal(findSpfRecord(txts), "v=spf1 include:_spf.google.com ~all");
  assert.equal(findSpfRecord(["nothing here"]), null);
  assert.equal(findDmarcRecord(["v=DMARC1; p=none"]), "v=DMARC1; p=none");
  assert.equal(findDkimRecord(["v=DKIM1; p=AAA"]), "v=DKIM1; p=AAA");
});

// ---------------------------------------------------------------------------
// Verdict builders
// ---------------------------------------------------------------------------

test("buildSpfCheck: verified for exactly one record, fails on none/multiple/null", () => {
  const ok = buildSpfCheck(["v=spf1 -all"]);
  assert.equal(ok.verified, true);
  assert.equal(ok.record, "v=spf1 -all");
  assert.equal(ok.error, null);

  assert.equal(buildSpfCheck(null).verified, false);
  assert.equal(buildSpfCheck(["no spf here"]).verified, false);

  const dup = buildSpfCheck(["v=spf1 a", "v=spf1 mx"]);
  assert.equal(dup.verified, false);
  assert.match(dup.error ?? "", /Multiple SPF/);
});

test("buildDmarcCheck: verified for one record, fails on none/multiple", () => {
  assert.equal(buildDmarcCheck(["v=DMARC1; p=none"]).verified, true);
  assert.equal(buildDmarcCheck(null).verified, false);
  assert.equal(buildDmarcCheck(["not dmarc"]).verified, false);
  const dup = buildDmarcCheck(["v=DMARC1; p=none", "v=DMARC1; p=reject"]);
  assert.equal(dup.verified, false);
  assert.match(dup.error ?? "", /Multiple DMARC/);
});

test("buildDkimCheck: needs a record with a non-empty p= key", () => {
  const ok = buildDkimCheck(["v=DKIM1; k=rsa; p=MIIBIjANBg=="], "default");
  assert.equal(ok.verified, true);
  assert.equal(ok.record, "v=DKIM1; k=rsa; p=MIIBIjANBg==");

  assert.equal(buildDkimCheck(null, "default").verified, false);
  assert.equal(buildDkimCheck(["no dkim"], "default").verified, false);

  const revoked = buildDkimCheck(["v=DKIM1; k=rsa; p="], "sel");
  assert.equal(revoked.verified, false);
  assert.match(revoked.error ?? "", /revoked/);
});

test("buildCnameCheck: verified when at least one CNAME target resolves", () => {
  assert.equal(buildCnameCheck(["track.provider.net"]).verified, true);
  assert.equal(buildCnameCheck(["track.provider.net"]).record, "track.provider.net");
  assert.equal(buildCnameCheck(null).verified, false);
  assert.equal(buildCnameCheck([]).verified, false);
});
